cat > /tmp/fix6.py << 'EOF'
import sys

# Read the file
with open('/testbed/sympy/core/add.py', 'r') as f:
    content = f.read()

# Find and replace the _eval_is_zero method
old_method = '''    def _eval_is_zero(self):
        if self.is_commutative is False:
            # issue 10528: there is no way to know if a nc symbol
            # is zero or not
            return
        nz = []
        z = 0
        im_or_z = False
        im = False
        for a in self.args:
            if a.is_real:
                if a.is_zero:
                    z += 1
                elif a.is_zero is False:
                    nz.append(a)
                else:
                    return
            elif a.is_imaginary:
                im = True
            elif (S.ImaginaryUnit*a).is_real:
                im_or_z = True
            else:
                return
        if z == len(self.args):
            return True
        if len(nz) == len(self.args):
            return None
        b = self.func(*nz)
        if b.is_zero:
            if not im_or_z and not im:
                return True
            if im and not im_or_z:
                return False
        if b.is_zero is False:
            return False
        # If we couldn't determine if the expression is zero, try expanding
        # to see if terms cancel out (e.g., (1+I)**2 - 2*I)
        expanded = self.expand()
        if expanded == 0:
            return True
        return None'''

new_method = '''    def _eval_is_zero(self):
        if self.is_commutative is False:
            # issue 10528: there is no way to know if a nc symbol
            # is zero or not
            return
        # Expand the expression to simplify it before checking
        # This is necessary to detect cases like (1+I)**2 - 2*I = 0
        expanded = self.expand()
        if expanded == 0:
            return True
        nz = []
        z = 0
        im_or_z = False
        im = False
        for a in expanded.args:
            if a.is_real:
                if a.is_zero:
                    z += 1
                elif a.is_zero is False:
                    nz.append(a)
                else:
                    return
            elif a.is_imaginary:
                im = True
            elif (S.ImaginaryUnit*a).is_real:
                im_or_z = True
            else:
                return
        if z == len(expanded.args):
            return True
        if len(nz) == len(expanded.args):
            return None
        b = expanded.func(*nz)
        if b.is_zero:
            if not im_or_z and not im:
                return True
            if im and not im_or_z:
                return False
        if b.is_zero is False:
            return False
        return None'''

if old_method in content:
    content = content.replace(old_method, new_method)
    with open('/testbed/sympy/core/add.py', 'w') as f:
        f.write(content)
    print("Successfully patched the file")
else:
    print("Could not find the method to patch")
    sys.exit(1)
